// Regenerate app/icons.css — a self-hosted subset of the Font Awesome icons this
// site actually uses. Run when an icon is added or removed:
//
//   node scripts/build-icon-css.mjs
//
// Why: the CDN stylesheet is 102KB and render-blocking, and it pulls a 150KB
// webfont, all to draw ~30 small glyphs. The generated file keeps the existing
// `.fas.fa-x` selectors, so no markup changes — each icon becomes a CSS mask over
// currentColor, which inherits colour and font-size exactly like the glyph did.
//
// Icons come from the Font Awesome Free npm package over jsDelivr (cdnjs does
// not publish the svgs/ folder). Licence: icons are CC BY 4.0, attributed in the
// generated file's header.
import fs from "node:fs";
import path from "node:path";

const VERSION = "6.4.0";
const BASE = `https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@${VERSION}/svgs`;
const OUT = path.join(process.cwd(), "app", "icons.css");

// Every icon referenced in app/ and components/, including the ones built at
// runtime from lib/categories.ts, lib/regions.ts and the province "tips" block.
// Keep in sync by grepping for `fa-` before running.
const SOLID = [
  "arrow-right", "bars", "bed", "bowl-food", "calendar-days", "camera-retro", "city",
  "clock", "coins", "diamond-turn-right", "envelope", "globe", "house",
  "location-dot", "mountain", "mug-hot", "phone", "route", "star",
  "store", "sun", "tag", "tractor", "umbrella-beach", "utensils", "water",
];
// Older Font Awesome names still used in the markup. FA6 renamed these and only
// serves them through its v4-compatibility shim, so the subset aliases them to
// the current file rather than making us touch 28 call sites.
const ALIASES = {
  "map-marker-alt": "location-dot",
  search: "magnifying-glass",
  times: "xmark", // the mobile menu's close state — Navbar swaps fa-bars/fa-times
};
const BRANDS = ["facebook-f", "instagram", "twitter"];

// Data URI that survives a CSS file unquoted-ish: keep it in double quotes and
// escape only what would break out of it.
const toDataUri = (svg) =>
  "url(\"data:image/svg+xml," +
  svg
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/"/g, "'")
    .replace(/#/g, "%23")
    .replace(/</g, "%3C")
    .replace(/>/g, "%3E")
    .replace(/\?/g, "%3F") +
  "\")";

async function fetchSvg(style, name) {
  const res = await fetch(`${BASE}/${style}/${name}.svg`);
  if (!res.ok) throw new Error(`${style}/${name} → HTTP ${res.status}`);
  return res.text();
}

const lines = [];
for (const [style, names] of [["solid", SOLID], ["brands", BRANDS]]) {
  for (const name of names) {
    lines.push(`.fa-${name} {\n  --fa-icon: ${toDataUri(await fetchSvg(style, name))};\n}`);
  }
}
for (const [alias, target] of Object.entries(ALIASES)) {
  lines.push(`.fa-${alias} {\n  --fa-icon: ${toDataUri(await fetchSvg("solid", target))};\n}`);
}

const css = `/* GENERATED by scripts/build-icon-css.mjs — do not edit by hand.
   Font Awesome Free ${VERSION} icons (CC BY 4.0), https://fontawesome.com/license/free
   Subset of the ${SOLID.length + BRANDS.length + Object.keys(ALIASES).length} icons this site uses, so the 102KB CDN stylesheet and its
   150KB webfont are not needed. Sized in em and painted with currentColor, so
   existing text-* and colour utilities keep working unchanged. */
.fas,
.fab {
  display: inline-block;
  width: 1em;
  height: 1em;
  vertical-align: -0.125em;
  background-color: currentColor;
  -webkit-mask: var(--fa-icon) no-repeat center;
  mask: var(--fa-icon) no-repeat center;
  -webkit-mask-size: contain;
  mask-size: contain;
}

${lines.join("\n")}
`;

fs.writeFileSync(OUT, css);
console.log(`wrote ${path.relative(process.cwd(), OUT)} — ${lines.length} icons, ${(css.length / 1024).toFixed(1)}KB`);
